def source_dir(row):
    c = row['catalog']
    rel = c.get('copy_dir', c.get('template'))
    if rel is None:
        rel = row['batch'] + '/' + c['path']
    return PACKAGE / rel

def collect():
    frozen = json.loads(execution_manifest().read_text())
    facit = json.loads((PACKAGE / 'FACIT.json').read_text())
    bound_reviews = {r['result_sha256']: r for r in json.loads((HERE / 'raw/REVIEW_DELTA.json').read_text())['records'] if r['eligible']}
    rows = []
    for r in frozen['executions']:
        ident = r['id']
        d = source_dir(r)
        j = json.loads((d / 'results.json').read_text()) if (d / 'results.json').exists() else {}
        ref = j.get('external_referent', facit.get(ident, {}).get('external_referent'))
        if ref is None:
            ref = {'kind': 'external_review', 'locator': str(d / 'README_DEMO.md'), 'compared_quantity': 'Scoped source-bound package delivery; see explicit independent review in batch metadata', 'refutes_us': True}
        review_fallbacks = {'PROOF_LANE_INFOLINK4': HERE.parent / 'LANE_XREVIEW_BATCH11/REVIEW_PROOF_LANE_INFOLINK4.json', 'FALT_TANDLAST': PACKAGE / 'batch18/reviews/REVIEW_SOL_FALT_TANDLAST_20261003.json', 'PROOF_LANE_INFOLINK3': PACKAGE / 'reviews/XREV_batch5_pkg/REVIEW_PROOF_LANE_INFOLINK3.json', 'X39': PACKAGE / 'reviews/XREV_batch7_pkg/REVIEW_LANE_X39_MANUSCRIPT_BITE.json'}
        if ident in review_fallbacks:
            review_path = review_fallbacks[ident]
            assert review_path.exists(), str(review_path)
            ref = {'kind': 'external_review', 'locator': str(review_path), 'compared_quantity': 'Independently reviewed source extraction, scientific scope and local reproduction', 'refutes_us': True}
        if ident in FACTS:
            (fact, knowledge, resolution) = FACTS[ident]
        else:
            q = facit[ident]
            v = q['primary_value']
            unit = q['units']
            fact = f'{v:.6g} {unit}' if isinstance(v, (int, float)) else f'{v} {unit}'
            knowledge = "Modelled/comparable; physical calibration unknown"
            resolution = {'X7': 'POPULATION; rapportkategorier PER_ARCH', 'X14': 'POPULATION; gruppmedel', 'X3': "POPULATION of PER_TOOTH -surface dimensions", 'X13': "POPULATION with PER_SURFACE_REGION - support", 'X5': 'PHENOMENOLOGICAL; injicerade motprov', 'X10': "POPULATION ; source and analytical fixture separately", 'X2': 'POPULATION; separata kohorter', 'PROOF_LANE': 'PHENOMENOLOGICAL; konstruktioner', 'X1B': 'PER_TOOTH; PHENOMENOLOGICAL modellindex', 'X17': "POPULATION ; source protocol", 'X12': 'POPULATION; annoterade PER_TOOTH-objekt', 'X4': 'POPULATION av PER_POINT-ytfel', 'X8': 'POPULATION av PER_TOOTH-platsbeslut', 'X9': 'PER_SURFACE_REGION; etikettgeometri', 'X15': 'POPULATION; geometri-scenarier', 'X21': 'POPULATION; rapportkategorier PER_ARCH', 'X22': 'PHENOMENOLOGICAL; simulerat bildscenario', 'X18': 'POPULATION av PER_TOOTH-modellsvar', 'X19': 'POPULATION; sensorgruppmedel', 'X20': 'PHENOMENOLOGICAL; geometriqueries'}[ident]
        rows.append({'demo_id': ident, 'label': LABELS[ident], 'reader_result': fact, 'knowledge_status': knowledge, 'resolution': resolution, 'source_reader': str(d / 'README_DEMO.md'), 'source_result': str(d / 'results.json'), 'source_result_sha256': sha(d / 'results.json') if (d / 'results.json').exists() else None, 'delivery_review_status': r['catalog'].get('source_review_status', r['catalog'].get('decision', r['catalog'].get('review_decision', 'UNKNOWN; see bundled independent review'))), 'claim_type': j.get('claim_type', r['catalog'].get('claim_type', 'capability')), 'external_referent': ref, 'execution_scope': r['scope']})
        reviewed_sha = r['catalog'].get('review_result_sha256')
        if reviewed_sha in bound_reviews:
            review = bound_reviews[reviewed_sha]
            index = json.loads((PACKAGE / r['batch'] / 'INDEX.json').read_text())
            entry = next((x for x in index['demos'] if x.get('demo_id', x.get('id')) == ident))
            snapshot = PACKAGE / r['batch'] / entry['source_result_snapshot']
            assert snapshot.is_file() and sha(snapshot) == reviewed_sha
            rows[-1]['delivery_review_status'] = review['demo_decision']
            rows[-1]['independent_review_binding'] = {'review_locator': review['path'], 'review_sha256': review['sha256'], 'reviewed_original_result_sha256': reviewed_sha, 'reviewed_original_snapshot': str(snapshot), 'packaged_result_sha256': rows[-1]['source_result_sha256'], 'scope': 'Original reviewed result + separately release-locked packaged derivative; no implied equality between their result hashes'}
    assert len(rows) == len(frozen['executions']) and len({r['demo_id'] for r in rows}) == len(rows)
    write(HERE / 'CURATED_DEMOS.json', rows)
    review_rows = []
    for batch in ['23', '24', '25']:
        root = HERE.parent / ('LANE_XREVIEW_BATCH' + batch)
        for f in sorted(root.glob('REVIEW_*.json')):
            j = json.loads(f.read_text())
            snapshot = HERE / 'raw/reviews' / ('batch' + batch) / f.name
            snapshot.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, snapshot)
            review_rows.append({'path': str(f), 'snapshot': str(snapshot), 'sha256': sha(f), 'job': j.get('job_id', j.get('job')), 'graph_decision': j.get('graph_decision'), 'demo_decision': j.get('demo_decision'), 'result_sha256': j.get('result_sha256'), 'eligible': j.get('graph_decision') in ['ACCEPT', 'ACCEPT_WITH_CORRECTION'] and j.get('demo_decision') in ['DEMO_READY', 'DEMO_READY_WITH_CORRECTION']})
    write(HERE / 'raw/REVIEW_DELTA.json', {'records': review_rows, 'retained': sum((r['eligible'] for r in review_rows)), 'rejected_records': sum((not r['eligible'] for r in review_rows)), 'denominator': len(review_rows), 'note': 'Earlier undecidable full-crown version is retained as a rejected record; batch25 reviews the later completed hash. Hunt versions receive no demo or status promotion.'})
    a = {r['demo_id'] for r in rows}
    b = a - {'X82'} | {'LANE_XBREAK_HUNT_2'}
    suff = {'summary_a': len(a), 'summary_b': len(b), 'identity_error': abs(len(a) - len(b)), 'float64_identity_error': abs(float(len(a)) - float(len(b))), 'consumer': 'Can the reviewed height-to-force demo be executed?', 'downstream_a': int('X82' in a), 'downstream_b': int('X82' in b), 'downstream_difference': int('X82' in a) - int('X82' in b), 'verdict': 'COUNT_IS_INSUFFICIENT', 'minimal_extension': 'Per-demo identity + validator scope + exact reviewed result binding', 'resolution': 'PHENOMENOLOGICAL', 'external_referent': 'Frozen active package indices versus independent batch23 UNDECIDABLE review for the substituted command'}
    assert suff['identity_error'] == 0 and suff['float64_identity_error'] == 0 and (suff['downstream_difference'] == 1)
    write(HERE / 'raw/SUFFICIENCY.json', suff)
if __name__ == '__main__':
    collect()
